class TransitionMatrix {
  public final long[][] matrix;

  public TransitionMatrix() {
    this.matrix = new long[4][4];
    for (int i = 0; i <= 3; i++) {
      for (int j = 0; j <= 3; j++) {
        this.matrix[i][j] = 0L;
      }
    }
  }

