  }

  public void set(int i, int j, long x) {
    this.matrix[i][j] = x;
  }

  public TransitionMatrix times(TransitionMatrix other) {
    final long modulo = 1000000007L;
    TransitionMatrix result = new TransitionMatrix();
    for (int i = 0; i <= 3; i++) {
      for (int j = 0; j <= 3; j++) {
        long x = 0L;
        for (int k = 0; k <= 3; k++) {
          x = (x + (this.get(i, k) * other.get(k, j))) % modulo;
        }
        result.set(i, j, x);
      }
    }
    return result;
  }
}

public class Main {

  static TransitionMatrix identity_matrix() {
    TransitionMatrix result = new TransitionMatrix();
    result.set(0, 0, 1L);
    result.set(1, 1, 1L);
    result.set(2, 2, 1L);
    result.set(3, 3, 1L);
